3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * Flags a soft duplicate: an owner that passed the hard-duplicate check (see
10	 * {@link RequireUniqueIdentity}) but still looks like it may duplicate an existing one because
11	 * it shares that owner's lastName (compared case-insensitively) and postcode while giving a
12	 * different telephone. Sets {@link Owner#getPossibleDuplicate() possibleDuplicate} true and
13	 * {@link Owner#getPossibleDuplicateOf() possibleDuplicateOf} to the matching owner's id;
14	 * otherwise leaves the flag false and no reference.
15	 *
16	 * <p>A declared household member — one that opted in with {@code sharesHousehold} to join an
17	 * existing (lastName, postcode) household — is never flagged: a declared member is not a
18	 * suspected duplicate.
19	 *
20	 * <p>Runs before {@link SaveOwner} so it compares only against already-stored owners and never
21	 * itself. When several owners match, the lowest id is chosen for a deterministic reference.
22	 */
23	public class FlagOwnerPossibleDuplicate {
24	
25	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
26	        Integer matchId = null;
27	        boolean declaredMember = Boolean.TRUE.equals(request.getSharesHousehold());
28	        if (!declaredMember && owner.getPostcode() != null) {
29	            for (Owner existing : ownerRepository.findAll()) {
30	                if (sameName(existing.getLastName(), owner.getLastName())
31	                        && owner.getPostcode().equals(existing.getPostcode())
32	                        && !sameTelephone(existing.getTelephone(), owner.getTelephone())
33	                        && (matchId == null || existing.getId() < matchId)) {
34	                    matchId = existing.getId();
35	                }
36	            }
37	        }
38	        owner.setPossibleDuplicate(matchId != null);
39	        owner.setPossibleDuplicateOf(matchId);
40	    }
41	
42	    private static boolean sameName(String a, String b) {
43	        return a == null ? b == null : a.equalsIgnoreCase(b);
44	    }
45	
46	    private static boolean sameTelephone(String a, String b) {
47	        return a == null ? b == null : a.equals(b);
48	    }
49	}
