3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Normalizes the owner email when one is supplied: an absent (null or blank) email is
9	 * left untouched, otherwise it must be a syntactically valid address (else a 400 via
10	 * {@link InvalidEmailException}) and is stored lower-cased. Mutates the published body in
11	 * place so later steps (and the response) see the canonical value.
12	 */
13	public class NormalizeOwnerEmail {
14	
15	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
16	        String email = request.getEmail();
17	        if (email == null || email.isBlank()) {
18	            return; // email is optional
19	        }
20	        String normalized = OwnerEmails.normalize(email);
21	        if (!OwnerEmails.isValid(normalized)) {
22	            throw new InvalidEmailException(email);
23	        }
24	        request.setEmail(normalized);
25	    }
26	}
