98	        }
99	        return Locality.forPostcode(owner.getPostcode());
100	    }
101	
102	    /** The IANA timezone name for the owner's region (see {@link Timezone} and {@link #locality}),
103	     * or null when the region has no known timezone. */
104	    default String timezone(Owner owner) {
105	        if (owner == null) {
106	            return null;
107	        }
108	        return Timezone.forRegion(locality(owner));
109	    }
110	
111	    /** The owner's honorific title and last name, space-separated (e.g. 'DR Who'); just the
112	     * last name when no title is stored. */
113	    default String salutation(Owner owner) {
114	        if (owner == null) {
115	            return null;
116	        }
117	        String title = owner.getTitle();
118	        if (title == null || title.isEmpty()) {
119	            return owner.getLastName();
120	        }
121	        return title + " " + owner.getLastName();
122	    }
123	
124	    /** Format the stored names as 'LastName, FirstName'. */
125	    default String displayName(Owner owner) {
126	        if (owner == null) {
127	            return null;
128	        }
129	        return owner.getLastName() + ", " + owner.getFirstName();
130	    }
131	
132	    /** The upper-cased first letters of firstName and lastName, dot-separated with a trailing dot (e.g. 'J.S.'). */
133	    default String initials(Owner owner) {
