140	    private static String initial(String name) {
141	        if (name == null || name.isEmpty()) {
142	            return "";
143	        }
144	        return Character.toUpperCase(name.charAt(0)) + ".";
145	    }
146	
147	    /**
148	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
