183	     */
184	    default Integer membershipPoints(Owner owner) {
185	        if (owner == null) {
186	            return null;
187	        }
188	        return MembershipPoints.of(owner);
189	    }
190	
191	    /**
192	     * The owner's numeric membership level: the value fixed at creation time (capped against the
